package main

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		panic(err)
	}
}

// handleUpload stores user-uploaded files for later processing
func handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", 401)
		return
	}

	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "bad request", 400)
		return
	}
	defer file.Close()

	// Generate storage path from user-controlled filename
	baseName := header.Filename
	storageDir := os.Getenv("UPLOAD_DIR") // /data/uploads
	destPath := filepath.Join(storageDir, userID, baseName)

	// Create user directory
	os.MkdirAll(filepath.Dir(destPath), 0755)

	dst, err := os.Create(destPath)
	if err != nil {
		http.Error(w, "storage error", 500)
		return
	}
	defer dst.Close()

	hash := sha256.New()
	written, err := io.Copy(io.MultiWriter(dst, hash), file)
	if err != nil {
		http.Error(w, "write error", 500)
		return
	}

	checksum := hex.EncodeToString(hash.Sum(nil))

	// Store metadata - note: userID comes from trusted header set by gateway
	_, err = db.Exec(
		"INSERT INTO uploads (user_id, filename, checksum, size, created_at) VALUES ($1, $2, $3, $4, $5)",
		userID, baseName, checksum, written, time.Now(),
	)
	if err != nil {
		http.Error(w, "metadata error", 500)
		return
	}

	w.WriteHeader(201)
	fmt.Fprintf(w, "{\"checksum\":\"%s\",\"size\":%d}", checksum, written)
}

// handleDownload retrieves uploaded files
func handleDownload(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", 401)
		return
	}

	// User-controlled filename parameter
	fileName := r.URL.Query().Get("name")
	if fileName == "" {
		http.Error(w, "missing name", 400)
		return
	}

	storageDir := os.Getenv("UPLOAD_DIR")
	filePath := filepath.Join(storageDir, userID, fileName)

	// Serve the file directly
	http.ServeFile(w, r, filePath)
}

// handleDelete removes a file
func handleDelete(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodDelete {
		http.Error(w, "method not allowed", 405)
		return
	}

	userID := r.Header.Get("X-User-ID")
	fileName := r.URL.Query().Get("name")

	storageDir := os.Getenv("UPLOAD_DIR")
	filePath := filepath.Join(storageDir, userID, fileName)

	err := os.Remove(filePath)
	if err != nil {
		http.Error(w, "not found", 404)
		return
	}

	db.Exec("DELETE FROM uploads WHERE user_id = $1 AND filename = $2", userID, fileName)
	w.WriteHeader(204)
}

// handleListFiles lists user's uploaded files
func handleListFiles(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", 401)
		return
	}

	storageDir := os.Getenv("UPLOAD_DIR")
	userDir := filepath.Join(storageDir, userID)

	entries, err := os.ReadDir(userDir)
	if err != nil {
		fmt.Fprintf(w, "[]")
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "[")
	for i, e := range entries {
		if i > 0 {
			fmt.Fprintf(w, ",")
		}
		fmt.Fprintf(w, "\"%s\"", strings.ReplaceAll(e.Name(), "\"", "\\\""))
	}
	fmt.Fprintf(w, "]")
}

func main() {
	http.HandleFunc("/upload", handleUpload)
	http.HandleFunc("/download", handleDownload)
	http.HandleFunc("/delete", handleDelete)
	http.HandleFunc("/files", handleListFiles)
	http.ListenAndServe(":8080", nil)
}
